    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    visited = set()

    def get_neighbors(r, c, h, w):
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                yield nr, nc

    def bfs_region(start_r, start_c):
        region = []
        stack = [(start_r, start_c)]
        while stack:
            cr, cc = stack.pop()
            if (cr, cc) in visited:
                continue
            visited.add((cr, cc))
            region.append((cr, cc))
            val = grid[cr][cc]
            for nr, nc in get_neighbors(cr, cc, h, w):
                if grid[nr][nc] == val and (nr, nc) not in visited:
                    stack.append((nr, nc))
