import json

grid_data = load()
test_input_grid = grid_data['Test input']

def find_and_fill_frames(grid, bg, fill_color_map):
    result = [row[:] for row in grid]
    visited = set()

    def get_neighbors(r, c, h, w):
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                yield nr, nc

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != bg and (r,c) not in visited:
                region = []
                stack = [(r,c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr,cc) in visited:
                        continue
                    visited.add((cr,cc))
                    region.append((cr,cc))
                    val = grid[cr][cc]
                    for nr, nc in get_neighbors(cr, cc, len(grid), len(grid[0])):
                        if grid[nr][nc] == val and (nr,nc) not in visited:
                            stack.append((nr,nc))

                rows = [p[0] for p in region]
                cols = [p[1] for p in region]
                min_r, max_r = min(rows), max(rows)
                min_c, max_c = min(cols), max(cols)
                height = max_r - min_r + 1
                width = max_c - min_c + 1

                expected_border = 2*height + 2*width - 4
                if len(region) == expected_border and height >= 3 and width >= 3:
                    fill_val = fill_color_map.get(val, bg)
                    for rr in range(min_r+1, max_r):
                        for cc in range(min_c+1, max_c):
                            result[rr][cc] = fill_val

    return result

